  string ConditionTokens(){return ConditionTokens(effectCondition==null?"":effectCondition.Text);}
  string ConditionTokens(string text){string raw=(text??"").Trim();if(raw.Length==0)return "";raw=Regex.Replace(raw,@"우선도\s*\+","우선도+");if(raw.Contains("「"))raw=raw.Replace("「"," ").Replace("」"," ");foreach(var pair in new[]{new[]{"타입 불일치","타입불일치"},new[]{"타입 일치","타입일치"},new[]{"효과가 굉장","효과가굉장"},new[]{"효과가 매우 굉장","효과가굉장"},new[]{"효과가 별로","효과가별로"},new[]{"효과가 매우 별로","효과가별로"},new[]{"효과 보통","효과보통"},new[]{"효과가 보통","효과보통"}})raw=raw.Replace(pair[0],pair[1]);raw=Regex.Replace(raw,@"위력\s*:?\s*(\d+)\s*(이하|이상)","위력$1$2");string bracketed=string.Concat(raw.Split(new[]{' ',',','，'},StringSplitOptions.RemoveEmptyEntries).Select(x=>"「"+Regex.Replace(x,@"^위력(\d+)(이하|이상)$","위력 $1 $2")+"」"));MoveCondition condition;return MoveCondition.TryParse(bracketed,out condition)?condition.Text:null;}
  string ConditionedTarget(string target){string tokens=ConditionTokens();if(string.IsNullOrEmpty(tokens))return target;if(target.EndsWith("기술의 위력")||target.EndsWith("기술의 명중"))return target.Replace("기술의",tokens+" 기술의");if(target.EndsWith("주는 대미지")||target.EndsWith("받는 대미지"))return target.Substring(0,target.Length-3)+tokens+" 기술의 대미지";return target;}
  string ConfiguredEffect(){string value=effectPreview==null?"":effectPreview.Text;string probability,effect;if(EffectNormalizer.TryProbabilityPrefix(value,out probability,out effect)){value=effect;}else probability=effectProbability==null?"":effectProbability.Text;if(effectSubject!=null&&effectSubject.Text!="자신"){string owner=effectSubject.Text;value=Regex.Replace(value,@"^자신의",owner+"의");value=Regex.Replace(value,@"^자신이",owner+(owner=="아군"?"이":"가"));value=Regex.Replace(value,@"^자신에게",owner+"에게");}return EffectNormalizer.WithProbability(probability,value);}
